{"command":"@'
$ErrorActionPreference = 'Stop'
$projectRoot = 'C:\Users\srija\SHIKDD-org\DevSage'
$csvPath = Join-Path $projectRoot '_bmad\_config\bmad-help.csv'

function Parse-SimpleYaml([string]$path) {
  $map = @{}
  if (!(Test-Path $path)) { return $map }
  Get-Content $path | ForEach-Object {
    $line = $_.Trim()
    if (-not $line -or $line.StartsWith('#')) { return }
    $idx = $line.IndexOf(':')
    if ($idx -lt 1) { return }
    $k = $line.Substring(0, $idx).Trim()
    $v = $line.Substring($idx + 1).Trim()
    if ($v.StartsWith('"') -and $v.EndsWith('"')) { $v = $v.Substring(1, $v.Length - 2) }
    if ($v.StartsWith("'") -and $v.EndsWith("'")) { $v = $v.Substring(1, $v.Length - 2) }
    $map[$k] = $v
  }
  return $map
}

function Resolve-Token([string]$token, $cfg) {
  if (-not $token) { return $null }
  $t = $token.Trim()
  if (-not $t) { return $null }

  $val = $t
  $val = $val.Replace('{project-root}', $projectRoot)

  $matches = [regex]::Matches($val, '\{([^}]+)\}')
  foreach ($m in $matches) {
    $key = $m.Groups[1].Value
    $cands = @($key, $key.Replace('-', '_'), $key.Replace('_', '-'))
    $rep = $null
    foreach ($c in $cands) {
      if ($cfg.ContainsKey($c)) { $rep = $cfg[$c]; break }
    }
    if ($rep) {
      $rep = $rep.Replace('{project-root}', $projectRoot)
      $val = $val.Replace($m.Value, $rep)
    }
  }

  if ($cfg.ContainsKey($val)) { $val = $cfg[$val] }
  else {
    $n1 = $val.Replace('-', '_')
    $n2 = $val.Replace('_', '-')
    if ($cfg.ContainsKey($n1)) { $val = $cfg[$n1] }
    elseif ($cfg.ContainsKey($n2)) { $val = $cfg[$n2] }
  }

  if ($val) { $val = $val.Replace('{project-root}', $projectRoot) }
  return $val
}

$moduleConfigs = @{}
Get-ChildItem -Path (Join-Path $projectRoot '_bmad') -Directory |
  Where-Object { $_.Name -ne '_config' } |
  ForEach-Object {
    $cfgPath = Join-Path $_.FullName 'config.yaml'
    $cfg = Parse-SimpleYaml $cfgPath
    $moduleConfigs[$_.Name] = $cfg
  }

$rows = Import-Csv $csvPath
$results = @()
foreach ($r in $rows) {
  $module = $r.module
  $cfg = @{}
  if ($module -and $moduleConfigs.ContainsKey($module)) { $cfg = $moduleConfigs[$module] }
  elseif ($moduleConfigs.ContainsKey('core')) { $cfg = $moduleConfigs['core'] }

  $locations = @()
  if ($r.'output-location') {
    $parts = $r.'output-location' -split '\|'
    foreach ($p in $parts) {
      $resolved = Resolve-Token $p $cfg
      if ($resolved) { $locations += $resolved }
    }
  }

  $artifactHits = @()
  foreach ($loc in $locations) {
    $candidatePath = $loc
    if ($candidatePath -and -not [System.IO.Path]::IsPathRooted($candidatePath)) {
      $candidatePath = Join-Path $projectRoot $candidatePath
    }
    if (-not $candidatePath) { continue }

    if (Test-Path $candidatePath) {
      $items = @()
      if ((Get-Item $candidatePath).PSIsContainer) {
        $items = Get-ChildItem -Path $candidatePath -Recurse -File -ErrorAction SilentlyContinue
      } else {
        $items = @(Get-Item $candidatePath)
      }
      if ($r.outputs) {
        $patterns = ($r.outputs -split '\|') | ForEach-Object { $_.Trim().ToLower() } | Where-Object { $_ }
        foreach ($it in $items) {
          $name = $it.Name.ToLower()
          $match = $false
          foreach ($pat in $patterns) {
            if ($pat -eq '*') { $match = $true; break }
            if ($name -like "*$pat*") { $match = $true; break }
          }
          if ($match) { $artifactHits += $it.FullName }
        }
      } elseif ($items.Count -gt 0) {
        $artifactHits += ($items | Select-Object -First 5 | ForEach-Object { $_.FullName })
      }
    }
  }

  $results += [PSCustomObject]@{
    module = $r.module
    phase = $r.phase
    code = $r.code
    name = $r.name
    command = $r.command
    required = $r.required
    resolved_locations = ($locations -join '; ')
    artifact_count = $artifactHits.Count
    sample_artifact = ($artifactHits | Select-Object -First 1)
  }
}

$moduleConfigs.GetEnumerator() | ForEach-Object {
  $m = $_.Key
  $cfg = $_.Value
  $lang = if ($cfg.ContainsKey('communication_language')) { $cfg['communication_language'] } else { '' }
  $pk = if ($cfg.ContainsKey('project_knowledge')) { $cfg['project_knowledge'] } else { '' }
  [PSCustomObject]@{ kind='module-config'; module=$m; communication_language=$lang; project_knowledge=$pk }
}
$results | Where-Object { $_.artifact_count -gt 0 } | Sort-Object module, phase, code
'@ | powershell -NoProfile -Command -"}

